{
  "schemaVersion": "bowerloom/v1alpha1",
  "parts": [
    {
      "id": "personal-assistant",
      "kind": "skill",
      "files": [
        "skills/personal-assistant/SKILL.md",
        "skills/personal-assistant/profile.json"
      ],
      "dependsOn": [],
      "requiredControls": [
        "installer-local-files-only",
        "installer-explicit-review"
      ]
    },
    {
      "id": "first-team",
      "kind": "team",
      "files": [
        "teams/first-team/assets/brief.json",
        "teams/first-team/assets/milestones.md",
        "teams/first-team/assets/working-agreement.md",
        "teams/first-team/maps/relay.json",
        "teams/first-team/maps/vines.json",
        "teams/first-team/prompts/lead.md",
        "teams/first-team/prompts/maker.md",
        "teams/first-team/prompts/reviewer.md",
        "teams/first-team/skills/bounded-draft.md",
        "teams/first-team/team.yaml"
      ],
      "dependsOn": [
        "personal-assistant"
      ],
      "requiredControls": [
        "installer-explicit-review"
      ]
    }
  ]
}

{
  "format": "trellis/relay-map/v0.7-alpha",
  "participants": [
    "lead",
    "maker",
    "reviewer"
  ],
  "routes": [
    {
      "fromOwner": "lead",
      "fromTask": "scope",
      "toOwner": "maker",
      "toTask": "draft",
      "delivery": "accepted-output",
      "bindings": [
        {
          "output": "document",
          "input": "scope"
        }
      ]
    },
    {
      "fromOwner": "lead",
      "fromTask": "scope",
      "toOwner": "reviewer",
      "toTask": "review",
      "delivery": "accepted-output",
      "bindings": [
        {
          "output": "document",
          "input": "scope"
        }
      ]
    },
    {
      "fromOwner": "maker",
      "fromTask": "draft",
      "toOwner": "reviewer",
      "toTask": "review",
      "delivery": "accepted-output",
      "bindings": [
        {
          "output": "document",
          "input": "draft"
        }
      ]
    }
  ]
}

{
  "format": "trellis/vines-map/v0.7-alpha",
  "purpose": "logging-only",
  "entries": [
    {
      "task": "scope",
      "owner": "lead",
      "evidence": [
        "runtime.status",
        "workspace.receipt",
        "test.acceptance"
      ],
      "sink": "local-session"
    },
    {
      "task": "draft",
      "owner": "maker",
      "evidence": [
        "runtime.status",
        "workspace.receipt",
        "test.acceptance"
      ],
      "sink": "local-session"
    },
    {
      "task": "review",
      "owner": "reviewer",
      "evidence": [
        "runtime.status",
        "workspace.receipt",
        "test.acceptance"
      ],
      "sink": "local-session"
    }
  ]
}

